import{_ as e,o as n,c as t,a0 as o}from"./chunks/framework.DhQjJcnt.js";const m=JSON.parse('{"title":"Kỹ năng: /docs-mark","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/docs-mark.md","filePath":"references/skills/docs-mark.md"}'),i={name:"references/skills/docs-mark.md"};function c(r,a,s,h,l,d){return n(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="ky-nang-docs-mark" tabindex="-1">Kỹ năng: <code>/docs-mark</code> <a class="header-anchor" href="#ky-nang-docs-mark" aria-label="Permalink to &quot;Kỹ năng: `/docs-mark`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>docs-mark</code> (thay thế cho skill cũ <code>/platform-mark</code>)</p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/docs-mark</code>.</li><li>Chạy sau quá trình Grill (phân tích) để đánh dấu (mark) lại các quyết định kỹ thuật đã được chốt (confirm).</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Thông số kỹ thuật từ <code>ir/spec.yaml</code>.</li><li>Các registries thuộc tầng giao diện UI (<code>registries/design.registry.json</code>) hoặc tầng logic (<code>registries/common.registry.json</code>).</li><li>Quyết định (confirm) của member sau khi chạy các grill (vd: chọn option A, B, C).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Cập nhật (Upsert) registry: Ghi nhận các tag và đánh dấu (marks) chính xác vào file registry.</li><li>Đánh dấu trên Docs Hub: Lưu các dấu vết kỹ thuật (SSOT) vào <code>surfaces/common/integrations/*</code> hoặc <code>surfaces/common/data-model/derived-data.md</code>.</li><li>Kích hoạt ArtifactGraph: Gọi các lệnh như <code>artifactgraph_remember</code> hoặc <code>artifactgraph_allowlist_check</code> (nếu tools khả dụng) để lưu kiến thức vào bộ nhớ chung.</li><li>Bàn giao (Handoff): Đẩy các phần validate chuyên sâu sang cho bộ code FE (<code>flowgrid gen:dry</code>). Không tự thay thế lệnh shell nếu thiếu tool.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Thuộc cụm Agent Common. Là chốt chặn đánh dấu các quyết định thiết kế kỹ thuật, mẫu thiết kế (common patterns) và các thành phần UI dùng chung.</li><li>Khi một tính năng cần tạo mới Component UI (<code>#needs-ui:</code>) hoặc Logic dùng chung (<code>#needs-common:</code>), kỹ năng này giúp ghi sổ (register) chúng lại để đội Frontend/Platform biết và thực thi.</li><li>Không tự động đánh tag nếu chưa hỏi và chốt với member.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/docs-mark</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',16)])])}const g=e(i,[["render",c]]);export{m as __pageData,g as default};
